// Laptop <-> phone sync: the Dart implementation checked against the vectors generated by
// the Python engine (core/conformance/sync/*.json), plus engine-level sync with in-memory stores.
import 'dart:convert';
import 'dart:io';

import 'package:flutter_test/flutter_test.dart';
import 'package:snapy/sync/commands.dart';
import 'package:snapy/sync/merge.dart';
import 'package:snapy/sync/pairing.dart';
import 'package:snapy/sync/protocol.dart';
import 'package:snapy/sync/sync_client.dart';
import 'package:snapy/sync/sync_store.dart';

Map<String, dynamic> vec(String name) {
  for (final base in ['../core/conformance/sync', 'core/conformance/sync']) {
    final f = File('$base/$name');
    if (f.existsSync()) return jsonDecode(f.readAsStringSync()) as Map<String, dynamic>;
  }
  throw StateError('missing vector $name');
}

String canon(Object? o) => utf8.decode(encodeJson(o));

Map<String, Rec> byId(List l) => {for (final r in l) (r as Map)['id'] as String: Map<String, dynamic>.from(r)};

void main() {
  group('handshake vectors', () {
    final data = vec('handshake.json');
    test('prologue', () => expect(data['prologue'], utf8.decode(prologue)));
    for (final c in (data['cases'] as List).cast<Map<String, dynamic>>()) {
      test('case ${c['name']}', () async {
        final cl = c['client'] as Map<String, dynamic>, sv = c['server'] as Map<String, dynamic>;
        for (final side in [cl, sv]) {
          expect(bytesToHex(await publicKeyOf(hexToBytes(side['static_priv']))), side['static_pub']);
          expect(bytesToHex(await publicKeyOf(hexToBytes(side['eph_priv']))), side['eph_pub']);
        }
        final psk = c['psk'] == null ? null : hexToBytes(c['psk']);
        final m1 = utf8.encode(c['m1'] as String), m2 = utf8.encode(c['m2'] as String);
        final th = await transcriptHash(m1, m2);
        expect(bytesToHex(th), c['th']);
        final ce = hexToBytes(cl['eph_priv']), cs = hexToBytes(cl['static_priv']);
        final eS = hexToBytes(sv['eph_pub']), sS = hexToBytes(sv['static_pub']);
        final dhs = [await dh(ce, eS), await dh(ce, sS), await dh(cs, eS), await dh(cs, sS)];
        final want = c['dh'] as Map;
        expect(dhs.map(bytesToHex).toList(), [want['ee'], want['es'], want['se'], want['ss']]);
        expect(bytesToHex(await saltFor(psk)), c['salt']);
        final keys = await deriveKeys(dhs[0], dhs[1], dhs[2], dhs[3], psk, th);
        expect(keys.toHex(), Map<String, String>.from(c['keys'] as Map));

        // the Dart client produces byte-identical messages and accepts the server's
        final hs = ClientHandshake(
            staticPriv: cs, deviceId: cl['id'], name: cl['name'], serverStaticPub: sS, mode: c['mode'], psk: psk,
            expectServerId: sv['id'], ephPriv: ce, nonce: hexToBytes(cl['nonce']));
        expect(utf8.decode(await hs.message1()), c['m1']);
        await hs.readMessage2(m2);
        await hs.readConfirm(utf8.encode(c['m3'] as String));
        expect(utf8.decode(await hs.message4()), c['m4']);

        if (psk != null) {
          final bad = ClientHandshake(
              staticPriv: cs, deviceId: cl['id'], name: cl['name'], serverStaticPub: sS, mode: 'pair',
              psk: List.filled(32, 0), expectServerId: sv['id'], ephPriv: ce, nonce: hexToBytes(cl['nonce']));
          await bad.message1();
          await bad.readMessage2(m2);
          expect(() => bad.readConfirm(utf8.encode(c['m3'] as String)), throwsA(isA<HandshakeException>()));
        }
        // a different laptop id is refused
        final other = ClientHandshake(
            staticPriv: cs, deviceId: cl['id'], name: cl['name'], serverStaticPub: sS, mode: c['mode'], psk: psk,
            expectServerId: 'windows-someoneelse', ephPriv: ce, nonce: hexToBytes(cl['nonce']));
        await other.message1();
        expect(() => other.readMessage2(m2), throwsA(isA<HandshakeException>()));
      });
    }
  });

  group('frame vectors', () {
    final data = vec('frames.json');
    final k = data['keys'] as Map;
    final c2s = hexToBytes(k['c2s']), s2c = hexToBytes(k['s2c']);

    test('phone decrypts laptop frames and encrypts identical frames', () async {
      final phone = Channel(c2s, s2c);
      for (final f in (data['s2c'] as List).cast<Map>()) {
        expect(utf8.decode(await phone.open(hexToBytes(f['frame']))), f['plaintext']);
      }
      for (final f in (data['c2s'] as List).cast<Map>()) {
        expect(bytesToHex(await phone.seal(utf8.encode(f['plaintext'] as String))), f['frame']);
      }
      final laptopSide = Channel(s2c, c2s);
      for (final f in (data['c2s'] as List).cast<Map>()) {
        expect(utf8.decode(await laptopSide.open(hexToBytes(f['frame']))), f['plaintext']);
      }
    });

    for (final n in (data['negative'] as List).cast<Map>()) {
      test('rejects: ${n['name']}', () async {
        final ch = Channel(List.filled(32, 0), n['direction'] == 'c2s' ? c2s : s2c)..recvCtr = n['expect_ctr'] as int;
        await expectLater(ch.open(hexToBytes(n['frame'])), throwsA(isA<FrameException>()));
        expect(ch.recvCtr, n['expect_ctr']);
      });
    }
  });

  group('merge vectors', () {
    final data = vec('merge.json');
    for (final c in (data['merge'] as List).cast<Map<String, dynamic>>()) {
      test('merge: ${c['name']}', () {
        final r = merge(byId(c['local'] as List), c['incoming'] as List,
            nowMs: parseTs(c['now']), maxSkewMs: (c['max_skew_s'] as int) * 1000);
        final e = c['expect'] as Map;
        expect(r.applied, List<String>.from(e['applied'] as List));
        expect(r.rejected, e['rejected']);
        expect(canon(r.merged), canon(e['merged']));
      });
    }
    test('to_send', () {
      for (final c in (data['to_send'] as List).cast<Map>()) {
        final got = toSend(byId(c['local'] as List), Map<String, dynamic>.from(c['peer_manifest'] as Map));
        expect(got.map((r) => r['id']).toList(), c['expect_ids']);
      }
    });
    test('purge', () {
      for (final c in (data['purge'] as List).cast<Map>()) {
        expect(purgeTombstones(byId(c['local'] as List), parseTs(c['now']), c['retention_days'] as int), c['expect_ids']);
      }
    });
    test('timestamps', () {
      final ts = data['timestamps'] as Map;
      for (final v in (ts['valid'] as List).cast<Map>()) {
        expect(parseTs(v['input']), v['ms'], reason: v['input'] as String);
      }
      for (final s in ts['invalid'] as List) {
        expect(() => parseTs(s), throwsFormatException, reason: s as String);
      }
      for (final f in (ts['format'] as List).cast<Map>()) {
        expect(fmtTs(f['ms'] as int), f['text']);
      }
    });
    test('commands', () {
      final cm = data['commands'] as Map;
      for (final c in cm['valid'] as List) {
        expect(validateCommand(c)['type'], (c as Map)['type']);
      }
      for (final c in cm['invalid'] as List) {
        expect(() => validateCommand(c), throwsA(isA<CommandException>()), reason: jsonEncode(c));
      }
    });
  });

  group('engine', () {
    test('two engines converge, incl. tombstones, via manifest/answer', () async {
      const now = 1794744000000; // 2026-11-15T12:00Z
      final lap = InMemorySyncStore('task');
      final ph = InMemorySyncStore('task');
      lap.localUpsert({'id': 't1', 'title': 'laptop'}, 'windows-a', now - 7200000);
      lap.localUpsert({'id': 't2', 'title': 'gone soon'}, 'windows-a', now - 7200000);
      ph.items['t2'] = {'id': 't2', 'updated': fmtTs(now - 3600000), 'device': 'android-b', 'deleted': true, 'schema_version': 1};
      ph.localUpsert({'id': 't3', 'title': 'phone'}, 'android-b', now - 3600000);
      final a = SyncEngine([lap], nowMs: () => now), b = SyncEngine([ph], nowMs: () => now);
      for (final m in await a.answer(await b.manifestMsg())) {
        if (m['type'] == 'records') await b.receive(m);
      }
      for (final m in await b.answer(await a.manifestMsg())) {
        if (m['type'] == 'records') await a.receive(m);
      }
      expect(canon(lap.items), canon(ph.items));
      expect(lap.items['t2']!['deleted'], true);
      expect(lap.items.length, 3);
      // nothing left to send
      final again = await a.answer(await b.manifestMsg());
      expect(again.single['type'], 'sync_end');
    });

    test('pairing payload parse', () {
      final good = jsonEncode({
        'v': 1, 't': 'snapy-pair', 'id': 'windows-a1', 'name': 'PC', 'hosts': ['192.168.1.4'], 'port': 47390,
        'secret': b64u(List.filled(32, 7)), 'pk': b64u(List.filled(32, 9)), 'exp': 1794744300
      });
      final p = PairingPayload.parse(good);
      expect(p.hosts, ['192.168.1.4']);
      expect(p.secret.length, 32);
      expect(p.expired(DateTime.fromMillisecondsSinceEpoch(1794744300000, isUtc: true)), true);
      expect(() => PairingPayload.parse('https://example.com'), throwsFormatException);
      expect(() => PairingPayload.parse(jsonEncode({'v': 1, 't': 'snapy-pair'})), throwsFormatException);
    });

    test('identity is created once and kept in the secure store only', () async {
      final ks = InMemoryKeyStore();
      final repo = PairingRepository(ks);
      final a = await repo.identity();
      final b = await repo.identity();
      expect(a.deviceId, b.deviceId);
      expect(a.publicKey, b.publicKey);
      expect(a.deviceId.startsWith('android-'), true);
      expect(a.toString().contains(b64u(a.privateKey)), false);
    });
  });
}
